pub fn list_models_argv(binary: &str, ssh_host: &str) -> Vec<String> {
    if ssh_host.is_empty() {
        return vec![binary.into(), "--list-models".into()];
    }
    vec![
        "ssh".into(),
        "-T".into(),
        "-o".into(),
        "BatchMode=yes".into(),
