        path,
        format!("#!/bin/sh\nif [ \"$1\" = \"{PROBE}\" ]; then exit 0; fi\n{body}"),
    )
    .unwrap_or_else(|error| panic!("could not write {}: {error}", path.display()));
    let mut permissions = std::fs::metadata(path).unwrap().permissions();
